H.background();
const c = Math.max(P.c, 0.25);
const L = 1 / (2 * Math.sqrt(c));
const yC = L;
const v = H.plot2d({ xMin: -2, xMax: 4, yMin: yC - 0.6, yMax: yC + 0.6 });
v.grid(); v.axes();
const f = x => {
  if (x + c < 0) return NaN;
  if (Math.abs(x) < 1e-6) return NaN;
  return (Math.sqrt(x + c) - Math.sqrt(c)) / x;
};
v.fn(f, { color: H.colors.accent, width: 3 });
v.fn(x => 1 / (Math.sqrt(x + c) + Math.sqrt(c)), { color: H.colors.good, width: 1.5, dash: [5, 4] });
